      "count": 0,
      "ipcCode": "",
      "fTerm": "ROLLING OF METAL (auxiliary operations used in connection with metal-working operations covered in <b>B21</b>, <u>see</u><b>B21C</b>; bending by rolling <b>B21D</b>; manufacture of particular objects, e.g. screws, wheels, rings, barrels, balls, by rolling <b>B21H</b>; pressure welding by means of a rolling mill <b>B23K 20/04</b>)<br><br><b><u>Note(s)</u></b><br><br><ul type=\"\"1\"\"><li>In this subclass, the following terms or expressions are used with the meanings indicated:<b>[2]</b><ul type=\"\"disc\"\"><li>&quot;rolling&quot; means rolling operations in which plastic deformations occur;</li><li>&quot;continuous process&quot; means a process employing a mill train designed to have the workpiece enter one pair of rolls before leaving the preceding pair.</li></ul></li></ul><br><br><b><u>Subclass indexes</u></b><br><table width=\"100%\"><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">METAL ROLLING IN GENERAL</td><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">General methods or apparatus</td><td><b>1/00</b>, <b>11/00</b>, <b>13/00</b>, <b>15/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Control or handling</td><td><b>35/00</b>, <b>37/00</b>, <b>38/00</b>, <b>39/00</b>, <b>41/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Safety, cooling, maintenance</td><td><b>28/00</b>, <b>33/00</b>, <b>43/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Details of rolling mills</td><td><b>27/00</b>, <b>29/00</b>, <b>31/00</b></td></p></tr></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">METAL ROLLING UNDER SPECIAL CONDITIONS</td><td><b>9/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">AUXILIARY OPERATIONS PERFORMED IN CONNECTION WITH METAL ROLLING</td><td><b>15/00</b>, <b>45/00</b>, <b>47/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">ROLLING SPECIAL ALLOYS</td><td><b>3/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">ROLLING TO PRODUCE PARTICULAR SHAPES</td><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Tubes</td><tr><td width=\"70%\"><p style=\"\"text-indent:3em;margin:0\"\">rolling methods</td><td><b>17/00-23/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:3em;margin:0\"\">mandrels, accessories</td><td><b>25/00</b></td></p></tr></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Extending closed shapes</td><td><b>5/00</b></td></p></tr></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">SUBJECT MATTER NOT PROVIDED FOR IN OTHER GROUPS OF THIS SUBCLASS</td><td><b>99/00</b></td></p></tr></table>",
      "childFlag": 0,
